function startOrder(modules) {
  const byId = new Map(modules.map((m) => [m.id, m]));
  const ordered = [];
  const visit = (m) => {
    if (ordered.includes(m.id)) return;
    for (const dep of m.dependencies ?? []) visit(byId.get(dep));
    ordered.push(m.id);
  };
  modules.forEach(visit);
  return ordered;
}

