async function start(ordered) {
  const initialized = [];
  const ready = [];
  try {
    for (const m of ordered) {
      initialized.push(m);
      await m.onInitialize?.();
    }
    for (const m of ordered) {
      await m.onReady?.();
      ready.push(m);
    }
  } catch (error) {
    for (const m of [...ready].reverse()) await m.onShutdown?.();
    for (const m of [...initialized].reverse()) await m.onDestroy?.();
    throw error;
  }
}

