async function stopWithin(stop, ms) {
  let timer;
  const timeout = new Promise((resolve) => {
    timer = setTimeout(() => resolve("timed out"), ms);
  });
  try {
    return await Promise.race([stop().then(() => "stopped"), timeout]);
  } finally {
    clearTimeout(timer);
  }
}

const quick = () => new Promise((resolve) => setTimeout(resolve, 5));
const hanging = () => new Promise(() => {});

console.log(await stopWithin(quick, 50));
console.log(await stopWithin(hanging, 20));
